-- 524: Original BrillaPrep NSMQ subj_nsmq_chemistry round_one beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_524_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_524_guard;
INSERT INTO _migration_524_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_r1_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_chem_electrochemistry' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In electrolysis, the electrode at which oxidation takes place is the' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Anode","B. Cathode","C. Salt bridge","D. Electrolyte"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Oxidation (loss of electrons) always occurs at the anode, while reduction occurs at the cathode — remembered by the mnemonic OIL RIG or “an ox, red cat”. The electrolyte is the conducting liquid, not an electrode.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_r1_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_524_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_r1_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_chem_equilibrium' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'According to Le Chatelier’s principle, increasing the pressure on the equilibrium N₂(g) + 3H₂(g) ⇌ 2NH₃(g) shifts the position of equilibrium' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Towards nitrogen and hydrogen","B. Towards ammonia, the side with fewer gas moles","C. It does not shift at all","D. Towards the side with more gas moles"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The forward reaction converts 4 moles of gas into 2 moles. Raising the pressure favours the side with fewer gas molecules, so the equilibrium shifts right towards NH₃. This is why the Haber process operates at high pressure.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_r1_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_524_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_r1_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_chem_organic' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which homologous series contains at least one carbon–carbon triple bond in every member?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Alkanes","B. Alkenes","C. Alkynes","D. Alcohols"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Alkynes are defined by a C≡C triple bond and follow the general formula CₙH₂ₙ₋₂, as in ethyne C₂H₂. Alkanes have only single bonds, alkenes have a C=C double bond, and alcohols are characterised by the −OH group.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_r1_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_524_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_r1_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_chem_bonding' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following substances has a giant covalent (macromolecular) structure?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Sodium chloride","B. Carbon dioxide","C. Copper","D. Diamond"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Diamond is a giant covalent lattice in which every carbon atom is bonded to four others, making it extremely hard. Sodium chloride is giant ionic, copper is giant metallic, and carbon dioxide is a simple molecular solid.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_r1_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
